contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address recipient, uint256 value) public {
        require(recipient != address(0));
        require(recipient != address(this));
        require(!c.frozenAccount(recipient));
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recipBefore = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        require(value <= ownerBefore);
        c.transfer(recipient, value); if (__ESBMC_reverted()) return;
        assert(
            c.totalSupply() == supplyBefore &&
            c.balanceOf(address(this)) == ownerBefore - value &&
            c.balanceOf(recipient) == recipBefore + value
        );
    }
    receive() external payable {}
}

